import React, { useState } from 'react';

function SchedulePage() {
  // 상단 날짜 선택 더미 데이터 (2026.09 기준)
  const dates = [
    { day: '10', label: '오늘', active: true },
    { day: '11', label: '금', active: false },
    { day: '12', label: '토', active: false },
    { day: '13', label: '일', active: false },
    { day: '14', label: '월', active: false },
    { day: '15', label: '화', active: false },
    { day: '16', label: '수', active: false },
  ];

  // 상영 영화 및 시간표 데이터
  const scheduleList = [
    {
      id: 1,
      cinema: "돌비시네마",
      hall: "Dolby Cinema (1관)",
      movieTitle: "오디세이",
      rating: "전체관람가",
      runtime: "142분",
      times: [
        { time: "10:00", seats: "120석", type: "조조" },
        { time: "13:10", seats: "85석", type: "일반" },
        { time: "16:40", seats: "12석", type: "일반" },
        { time: "20:00", seats: "0석", type: "마감", soldOut: true }
      ]
    },
    {
      id: 2,
      cinema: "일반상영관",
      hall: "2관",
      movieTitle: "싱 어 게인",
      rating: "12세이상관람가",
      runtime: "110분",
      times: [
        { time: "11:20", seats: "90석", type: "조조" },
        { time: "14:30", seats: "140석", type: "일반" },
        { time: "17:50", seats: "60석", type: "일반" }
      ]
    }
  ];

  const [selectedDate, setSelectedDate] = useState('10');

  return (
    <div className="w-full bg-[#f8f9fa] min-h-screen py-10 text-zinc-800">
      <div className="max-w-6xl mx-auto px-6">
        
        {/* 페이지 타이틀 */}
        <div className="mb-6">
          <h2 className="text-2xl font-black text-zinc-900 tracking-tight">상영시간표</h2>
          <p className="text-xs text-zinc-500 mt-1">메가박스 전국의 상영시간표를 한눈에 확인하세요.</p>
        </div>

        {/* 날짜 선택 바 */}
        <div className="bg-white border border-zinc-200 rounded-2xl p-4 mb-8 shadow-sm flex items-center justify-between overflow-x-auto">
          <div className="flex items-center gap-3">
            {dates.map((item) => (
              <button
                key={item.day}
                onClick={() => setSelectedDate(item.day)}
                className={`flex flex-col items-center px-4 py-2.5 rounded-xl transition ${
                  selectedDate === item.day 
                    ? 'bg-[#503396] text-white font-bold shadow' 
                    : 'bg-zinc-100 text-zinc-600 hover:bg-zinc-200'
                }`}
              >
                <span className="text-[10px] opacity-80">{item.label}</span>
                <span className="text-lg font-black">{item.day}</span>
              </button>
            ))}
          </div>
          <div className="text-xs font-bold text-zinc-500">
            2026.09.{selectedDate} 선택됨
          </div>
        </div>

        {/* 상영시간표 목록 영역 */}
        <div className="space-y-4">
          {scheduleList.map((item) => (
            <div key={item.id} className="bg-white border border-zinc-200 rounded-2xl p-6 shadow-sm">
              
              {/* 영화관 및 상영관 정보 */}
              <div className="flex justify-between items-center border-b border-zinc-100 pb-4 mb-4">
                <div>
                  <span className="text-xs font-bold text-[#503396] bg-purple-50 px-2 py-1 rounded mr-2">
                    {item.cinema}
                  </span>
                  <span className="text-sm font-bold text-zinc-700">{item.hall}</span>
                </div>
                <div className="text-xs text-zinc-400 font-medium">
                  {item.rating} | {item.runtime}
                </div>
              </div>

              {/* 영화 제목 및 시간대 슬롯 */}
              <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <div>
                  <h3 className="text-lg font-black text-zinc-900 mb-1">{item.movieTitle}</h3>
                </div>

                {/* 상영 시간 버튼들 */}
                <div className="flex flex-wrap gap-3">
                  {item.times.map((t, idx) => (
                    <div 
                      key={idx}
                      className={`border rounded-xl px-4 py-2 text-center transition ${
                        t.soldOut 
                          ? 'bg-zinc-100 border-zinc-200 text-zinc-400 cursor-not-allowed' 
                          : 'border-zinc-300 hover:border-[#503396] cursor-pointer hover:shadow-md'
                      }`}
                    >
                      <div className="text-sm font-black text-zinc-900">{t.time}</div>
                      <div className="text-[10px] text-zinc-500 font-medium flex gap-1 justify-center mt-0.5">
                        <span className={t.soldOut ? 'text-red-500 font-bold' : 'text-teal-600 font-bold'}>{t.seats}</span>
                        <span>({t.type})</span>
                      </div>
                    </div>
                  ))}
                </div>
              </div>

            </div>
          ))}
        </div>

      </div>
    </div>
  );
}

export default SchedulePage;
